def transform(grid):
    # The objects are monochrome filled blobs on a noisy field. The local color transitions,
    # rather than each color-count globally, reveal their intended footprints.
    from collections import deque
    h,w=len(grid),len(grid[0]); seen=set(); blobs=[]
    for r in range(h):
        for c in range(w):
            col=grid[r][c]
            if col in (0,7,9) or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft();cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
                        seen.add((yy,xx));q.append((yy,xx))
            blobs.append((col,cells))
    col,cells=max(blobs,key=lambda z:len(z[1]))
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
    return [[col]*(c1-c0-1) for _ in range(r1-r0-1)]

